<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/integrations.php';
if(!hash_equals($_SESSION['drive_oauth_state']??'',$_GET['state']??'')||empty($_GET['code'])){http_response_code(400);exit('Invalid OAuth response.');}$config=integrationConfig('google_drive');$client=$config['client_id']??getenv('GOOGLE_CLIENT_ID');$secret=integrationSecret($config,'client_secret')?:getenv('GOOGLE_CLIENT_SECRET');$redirect='http://127.0.0.1:8001/drive_callback.php';if(!$client||!$secret){http_response_code(500);exit('Google OAuth is not configured.');}$post=http_build_query(['code'=>$_GET['code'],'client_id'=>$client,'client_secret'=>$secret,'redirect_uri'=>$redirect,'grant_type'=>'authorization_code']);$ch=curl_init('https://oauth2.googleapis.com/token');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$post,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/x-www-form-urlencoded'],CURLOPT_TIMEOUT=>20]);$raw=curl_exec($ch);$token=json_decode((string)$raw,true);if(empty($token['access_token'])){http_response_code(502);exit('Drive token exchange failed.');}$config['encrypted_token']=encryptSecret(json_encode($token));saveIntegration('google_drive','connected',$config);unset($_SESSION['drive_oauth_state']);header('Location: integrations.php?connected=1');
